import{_ as t,o as e,c as d,a2 as n}from"./chunks/framework.D8Tso2Ul.js";const h=JSON.parse('{"title":"Base de datos (DynamoDB)","description":"","frontmatter":{},"headers":[],"relativePath":"arquitectura/base-de-datos.md","filePath":"arquitectura/base-de-datos.md"}'),s={name:"arquitectura/base-de-datos.md"};function o(r,a,i,l,c,p){return e(),d("div",null,[...a[0]||(a[0]=[n(`<h1 id="base-de-datos-dynamodb" tabindex="-1">Base de datos (DynamoDB) <a class="header-anchor" href="#base-de-datos-dynamodb" aria-label="Permalink to &quot;Base de datos (DynamoDB)&quot;">​</a></h1><p>El sistema usa <strong>AWS DynamoDB</strong> con 11 tablas, todas en <code>BillingMode PAY_PER_REQUEST</code>. El diseño prioriza el aislamiento por tenant y las consultas por Query (nunca Scan sin filtro de tenant).</p><h2 id="jerarquia-de-entidades" tabindex="-1">Jerarquía de entidades <a class="header-anchor" href="#jerarquia-de-entidades" aria-label="Permalink to &quot;Jerarquía de entidades&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tenant</span></span>
<span class="line"><span>  ├── Obra</span></span>
<span class="line"><span>  │     ├── Documentos</span></span>
<span class="line"><span>  │     ├── Actividades</span></span>
<span class="line"><span>  │     └── Incidentes</span></span>
<span class="line"><span>  └── Persona</span></span>
<span class="line"><span>        ├── Firmas</span></span>
<span class="line"><span>        └── Asignaciones</span></span></code></pre></div><h2 id="las-11-tablas" tabindex="-1">Las 11 tablas <a class="header-anchor" href="#las-11-tablas" aria-label="Permalink to &quot;Las 11 tablas&quot;">​</a></h2><h3 id="_1-tenantstable" tabindex="-1">1. TenantsTable <a class="header-anchor" href="#_1-tenantstable" aria-label="Permalink to &quot;1. TenantsTable&quot;">​</a></h3><p>Registro de empresas clientes del SaaS.</p><table tabindex="0"><thead><tr><th>Elemento</th><th>Valor</th></tr></thead><tbody><tr><td>PK</td><td><code>TENANT#{tenantId}</code></td></tr><tr><td>SK</td><td><code>METADATA#{tenantId}</code></td></tr><tr><td>GSI slug-index</td><td>PK: <code>slug</code></td></tr><tr><td>GSI status-index</td><td>PK: <code>estado</code></td></tr></tbody></table><h3 id="_2-obrastable" tabindex="-1">2. ObrasTable <a class="header-anchor" href="#_2-obrastable" aria-label="Permalink to &quot;2. ObrasTable&quot;">​</a></h3><p>Obras / proyectos de construcción de un tenant.</p><table tabindex="0"><thead><tr><th>Elemento</th><th>Valor</th></tr></thead><tbody><tr><td>PK</td><td><code>TENANT#{tenantId}</code></td></tr><tr><td>SK</td><td><code>OBRA#{obraId}</code></td></tr><tr><td>GSI obraId-index</td><td>PK: <code>obraId</code></td></tr></tbody></table><h3 id="_3-personastable" tabindex="-1">3. PersonasTable <a class="header-anchor" href="#_3-personastable" aria-label="Permalink to &quot;3. PersonasTable&quot;">​</a></h3><p>Identidad unificada (reemplaza Users y Workers).</p><table tabindex="0"><thead><tr><th>Elemento</th><th>Valor</th></tr></thead><tbody><tr><td>PK</td><td><code>TENANT#{tenantId}</code></td></tr><tr><td>SK</td><td><code>PERSONA#{personaId}</code></td></tr><tr><td>GSI personaId-index</td><td>PK: <code>personaId</code></td></tr><tr><td>GSI email-index</td><td>PK: <code>email</code></td></tr><tr><td>GSI tenantRut-index</td><td>PK: <code>tenantId</code>, SK: <code>rut</code></td></tr></tbody></table><h3 id="_4-documentostable" tabindex="-1">4. DocumentosTable <a class="header-anchor" href="#_4-documentostable" aria-label="Permalink to &quot;4. DocumentosTable&quot;">​</a></h3><p>Documentos del sistema, clasificados en obra / diario.</p><table tabindex="0"><thead><tr><th>Elemento</th><th>Valor</th></tr></thead><tbody><tr><td>PK</td><td><code>TENANT#{tenantId}</code></td></tr><tr><td>SK</td><td><code>DOC#{clasificacion}#{documentoId}</code></td></tr><tr><td>GSI documentoId-index</td><td>PK: <code>documentoId</code></td></tr><tr><td>GSI obraClasificacion-index</td><td>PK: <code>obraId</code>, SK: <code>clasificacion</code></td></tr></tbody></table><h3 id="_5-activitiestable" tabindex="-1">5. ActivitiesTable <a class="header-anchor" href="#_5-activitiestable" aria-label="Permalink to &quot;5. ActivitiesTable&quot;">​</a></h3><p>Charlas, capacitaciones, inspecciones, ART.</p><table tabindex="0"><thead><tr><th>Elemento</th><th>Valor</th></tr></thead><tbody><tr><td>PK</td><td><code>activityId</code></td></tr><tr><td>GSI tenantId-index</td><td>PK: <code>tenantId</code></td></tr></tbody></table><h3 id="_6-incidentstable" tabindex="-1">6. IncidentsTable <a class="header-anchor" href="#_6-incidentstable" aria-label="Permalink to &quot;6. IncidentsTable&quot;">​</a></h3><p>Reportes de accidentes, incidentes y condiciones subestándar.</p><table tabindex="0"><thead><tr><th>Elemento</th><th>Valor</th></tr></thead><tbody><tr><td>PK</td><td><code>incidentId</code></td></tr><tr><td>GSI tenantId-fecha-index</td><td>PK: <code>tenantId</code>, SK: <code>fecha</code></td></tr></tbody></table><h3 id="_7-signaturestable" tabindex="-1">7. SignaturesTable <a class="header-anchor" href="#_7-signaturestable" aria-label="Permalink to &quot;7. SignaturesTable&quot;">​</a></h3><p>Registro inmutable de todas las firmas digitales.</p><table tabindex="0"><thead><tr><th>Elemento</th><th>Valor</th></tr></thead><tbody><tr><td>PK</td><td><code>signatureId</code></td></tr><tr><td>GSI requestId-index</td><td>PK: <code>requestId</code></td></tr><tr><td>GSI tenantId-index</td><td>PK: <code>tenantId</code></td></tr><tr><td>GSI personaId-index</td><td>PK: <code>personaId</code></td></tr></tbody></table><h3 id="_8-signaturerequeststable" tabindex="-1">8. SignatureRequestsTable <a class="header-anchor" href="#_8-signaturerequeststable" aria-label="Permalink to &quot;8. SignatureRequestsTable&quot;">​</a></h3><p>Solicitudes de firma enviadas a personas.</p><table tabindex="0"><thead><tr><th>Elemento</th><th>Valor</th></tr></thead><tbody><tr><td>PK</td><td><code>requestId</code></td></tr><tr><td>GSI tenantId-index</td><td>PK: <code>tenantId</code></td></tr></tbody></table><h3 id="_9-surveystable" tabindex="-1">9. SurveysTable <a class="header-anchor" href="#_9-surveystable" aria-label="Permalink to &quot;9. SurveysTable&quot;">​</a></h3><p>Encuestas de seguridad y salud.</p><table tabindex="0"><thead><tr><th>Elemento</th><th>Valor</th></tr></thead><tbody><tr><td>PK</td><td><code>surveyId</code></td></tr><tr><td>GSI tenantId-index</td><td>PK: <code>tenantId</code></td></tr></tbody></table><h3 id="_10-inboxtable" tabindex="-1">10. InboxTable <a class="header-anchor" href="#_10-inboxtable" aria-label="Permalink to &quot;10. InboxTable&quot;">​</a></h3><p>Mensajería interna y notificaciones.</p><table tabindex="0"><thead><tr><th>Elemento</th><th>Valor</th></tr></thead><tbody><tr><td>PK</td><td><code>recipientId</code> (personaId)</td></tr><tr><td>SK</td><td><code>messageId</code></td></tr><tr><td>GSI senderId-createdAt-index</td><td>PK: <code>senderId</code>, SK: <code>createdAt</code></td></tr></tbody></table><h3 id="_11-sessionstable" tabindex="-1">11. SessionsTable <a class="header-anchor" href="#_11-sessionstable" aria-label="Permalink to &quot;11. SessionsTable&quot;">​</a></h3><p>Sesiones de autenticación.</p><table tabindex="0"><thead><tr><th>Elemento</th><th>Valor</th></tr></thead><tbody><tr><td>PK</td><td><code>sessionId</code></td></tr><tr><td>TTL</td><td><code>ttl</code> (Unix timestamp, expiración automática)</td></tr></tbody></table><h2 id="estructura-de-almacenamiento-s3" tabindex="-1">Estructura de almacenamiento S3 <a class="header-anchor" href="#estructura-de-almacenamiento-s3" aria-label="Permalink to &quot;Estructura de almacenamiento S3&quot;">​</a></h2><p>Un solo bucket compartido con aislamiento por prefijo de tenant:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hackaton-documents-{stage}/</span></span>
<span class="line"><span>  tenants/</span></span>
<span class="line"><span>    {tenantId}/</span></span>
<span class="line"><span>      config/</span></span>
<span class="line"><span>        logo.webp</span></span>
<span class="line"><span>      obras/</span></span>
<span class="line"><span>        {obraId}/</span></span>
<span class="line"><span>          fase-excavacion/</span></span>
<span class="line"><span>            documento.pdf</span></span>
<span class="line"><span>          fase-obra-gruesa/</span></span>
<span class="line"><span>            procedimiento.pdf</span></span>
<span class="line"><span>      personas/</span></span>
<span class="line"><span>        {personaId}/</span></span>
<span class="line"><span>          firma-enrolamiento.png</span></span>
<span class="line"><span>      evidencias/</span></span>
<span class="line"><span>        {incidentId}/</span></span>
<span class="line"><span>          foto1.jpg</span></span></code></pre></div><p>La descarga de archivos se hace mediante <strong>URLs prefirmadas (presigned)</strong> de S3, con acceso temporal y seguro.</p><h2 id="principios-de-diseno" tabindex="-1">Principios de diseño <a class="header-anchor" href="#principios-de-diseno" aria-label="Permalink to &quot;Principios de diseño&quot;">​</a></h2><ol><li><strong>Aislamiento por tenant</strong>: toda tabla operacional incluye <code>tenantId</code>. Nunca se usa Scan sin filtro de tenant.</li><li><strong>Fuente del tenantId</strong>: se extrae del JWT, jamás del body del request.</li><li><strong>Una sola identidad</strong>: <code>Persona</code> unifica Users y Workers — un ID, un PIN hash.</li><li><strong>Documentos con doble clasificación</strong>: <code>obra</code> (obligatorios por fase) y <code>diario</code> (asignados a personas).</li></ol><p>Ver <a href="/manual/arquitectura/multi-tenant.html">Multi-tenant</a> para el detalle del aislamiento.</p>`,45)])])}const u=t(s,[["render",o]]);export{h as __pageData,u as default};
